// Rhythm manifest (public/rhythms.json, generated by scripts/build-rhythms.mjs).

import { createStore } from '../lib/store';

export interface Rhythm {
  id: string;
  title: string;
  category: string;
  meter?: string;
  /** Tempo the loop was recorded at. */
  bpm?: number;
  /** Recording speeds up to this tempo (kept whole). */
  bpmTo?: number;
  /** Tempo guessed from the audio (no tempo in the file name). */
  bpmEstimated?: boolean;
  file: string;
  /** Seconds */
  duration: number;
  size: number;
}

export interface Category {
  id: string;
  label: string;
}

export interface RhythmCatalog {
  loaded: boolean;
  error?: string;
  categories: Category[];
  rhythms: Rhythm[];
}

export const catalog = createStore<RhythmCatalog>({ loaded: false, categories: [], rhythms: [] });

export function sanitizeCatalog(raw: unknown): Pick<RhythmCatalog, 'categories' | 'rhythms'> {
  const r = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
  const categories = (Array.isArray(r.categories) ? r.categories : [])
    .filter((c): c is Category => !!c && typeof c.id === 'string' && typeof c.label === 'string')
    .map((c) => ({ id: c.id, label: c.label }));
  const rhythms: Rhythm[] = [];
  for (const x of Array.isArray(r.rhythms) ? r.rhythms : []) {
    if (!x || typeof x.id !== 'string' || typeof x.file !== 'string' || typeof x.title !== 'string') continue;
    rhythms.push({
      id: x.id,
      title: x.title,
      category: typeof x.category === 'string' ? x.category : '',
      meter: typeof x.meter === 'string' ? x.meter : undefined,
      bpm: typeof x.bpm === 'number' && x.bpm >= 20 && x.bpm <= 400 ? x.bpm : undefined,
      bpmTo: typeof x.bpmTo === 'number' ? x.bpmTo : undefined,
      bpmEstimated: x.bpmEstimated === true,
      file: x.file,
      duration: typeof x.duration === 'number' ? x.duration : 0,
      size: typeof x.size === 'number' ? x.size : 0,
    });
  }
  return { categories, rhythms };
}

export async function loadCatalog(): Promise<void> {
  try {
    const res = await fetch('rhythms.json', { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    catalog.set({ loaded: true, ...sanitizeCatalog(await res.json()) });
  } catch (e) {
    catalog.set((c) => ({ ...c, loaded: true, error: 'Ritim listesi yüklenemedi. İnternet bağlantınızı kontrol edin.' }));
    console.warn(e);
  }
}

export const rhythmById = (id: string | undefined): Rhythm | undefined =>
  id ? catalog.get().rhythms.find((r) => r.id === id) : undefined;

export const categoryLabel = (id: string): string => catalog.get().categories.find((c) => c.id === id)?.label ?? id;

/** "2/4 · Halay" style subtitle parts. */
export function rhythmSubtitle(r: Rhythm): string {
  const cat = categoryLabel(r.category);
  const parts = [r.meter, cat !== r.meter && fold(cat) !== fold(r.title) ? cat : undefined].filter(Boolean);
  return parts.join(' · ');
}

/** Lowercase, Turkish letters folded to ASCII: "Kaşıklı" → "kasikli". */
export function fold(s: string): string {
  return s
    .toLocaleLowerCase('tr')
    .replace(/[çğıöşü]/g, (c) => ({ ç: 'c', ğ: 'g', ı: 'i', ö: 'o', ş: 's', ü: 'u' })[c] ?? c)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
}

export function searchRhythms(list: readonly Rhythm[], query: string, category?: string): Rhythm[] {
  const words = fold(query).split(/\s+/).filter(Boolean);
  return list.filter((r) => {
    if (category && r.category !== category) return false;
    if (!words.length) return true;
    const hay = fold(`${r.title} ${r.meter ?? ''} ${categoryLabel(r.category)} ${r.bpm ?? ''}`);
    return words.every((w) => hay.includes(w));
  });
}

export const formatTime = (s: number): string => {
  const t = Math.max(0, Math.floor(s));
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
};
